/**
 * Phase Derivation Module
 *
 * Derives TDD phase from task data using SHAs as completion markers.
 * All phases have startedAt/completedAt timestamps for metrics,
 * but derivation uses SHAs only (gapless forward walk).
 */
const DEFAULT_CONFIG = {
    combineRedGreenCommits: false,
    enableAdversarial: true,
    hasMutantCapability: false,
};
/**
 * Returns the ordered list of enabled pipeline phases based on config.
 */
export function getActivePipeline(config) {
    const phases = ['red'];
    if (!config.combineRedGreenCommits) {
        phases.push('green');
    }
    if (config.enableAdversarial) {
        phases.push('adversarial', 'adversarial-refactor');
    }
    if (config.hasMutantCapability) {
        phases.push('mutant', 'mutant-refactor');
    }
    phases.push('complete');
    return phases;
}
/**
 * Derives the current TDD phase by walking forward through the pipeline.
 * The first phase without its completion SHA is the current phase.
 * Timestamps are ignored — only SHAs determine phase.
 */
export function derivePhase(task, config = DEFAULT_CONFIG) {
    // No redStartedAt = not started
    if (!task.redStartedAt)
        return 'idle';
    // Red: waiting for test commit
    if (!task.testCommitSha)
        return 'red';
    // Green: waiting for impl commit (skip in combined mode where commitSha = testCommitSha)
    if (!task.commitSha) {
        return config.combineRedGreenCommits ? 'red' : 'green';
    }
    // Adversarial review
    if (config.enableAdversarial) {
        if (!task.adversarialReviewSha)
            return 'adversarial';
        // Needs refactoring? Check for refactor commit
        if (task.adversarialVerdict === 'needs-refactoring') {
            if (!task.adversarialRefactorCommitSha)
                return 'adversarial-refactor';
        }
    }
    // Mutant review
    if (config.hasMutantCapability) {
        if (!task.mutantReviewSha)
            return 'mutant';
        if (task.mutantVerdict === 'needs-refactoring') {
            if (!task.mutantRefactorCommitSha)
                return 'mutant-refactor';
        }
    }
    return 'complete';
}
/**
 * Checks if a specific phase has its completion SHA set.
 */
export function isPhaseComplete(task, phase) {
    switch (phase) {
        case 'red':
            return !!task.testCommitSha;
        case 'green':
            return !!task.commitSha;
        case 'adversarial':
            return !!task.adversarialReviewSha;
        case 'adversarial-refactor':
            return !!task.adversarialRefactorCommitSha;
        case 'mutant':
            return !!task.mutantReviewSha;
        case 'mutant-refactor':
            return !!task.mutantRefactorCommitSha;
        case 'complete':
            return false; // "complete" is a terminal state, not a phase with a SHA
        case 'idle':
            return false;
    }
}
/**
 * Checks if a phase is currently in progress (previous phase done, this phase not done).
 * Uses SHAs to determine boundaries.
 */
export function isPhaseInProgress(task, phase) {
    switch (phase) {
        case 'red':
            return !!task.redStartedAt && !task.testCommitSha;
        case 'green':
            return !!task.testCommitSha && !task.commitSha;
        case 'adversarial':
            return !!task.commitSha && !task.adversarialReviewSha;
        case 'adversarial-refactor':
            return (!!task.adversarialReviewSha &&
                task.adversarialVerdict === 'needs-refactoring' &&
                !task.adversarialRefactorCommitSha);
        case 'mutant':
            return isAdversarialDone(task) && !task.mutantReviewSha;
        case 'mutant-refactor':
            return (!!task.mutantReviewSha &&
                task.mutantVerdict === 'needs-refactoring' &&
                !task.mutantRefactorCommitSha);
        default:
            return false;
    }
}
/**
 * Checks if all enabled pipeline stages have their completion SHAs.
 */
export function isTaskComplete(task, config = DEFAULT_CONFIG) {
    return derivePhase(task, config) === 'complete';
}
/** Timestamp field mapping for each phase */
const PHASE_TIMESTAMPS = {
    red: { startedAt: 'redStartedAt', completedAt: 'redCompletedAt' },
    green: { startedAt: 'greenStartedAt', completedAt: 'greenCompletedAt' },
    adversarial: { startedAt: 'adversarialStartedAt', completedAt: 'adversarialCompletedAt' },
    'adversarial-refactor': { startedAt: 'adversarialRefactorStartedAt', completedAt: 'adversarialRefactorCompletedAt' },
    mutant: { startedAt: 'mutantStartedAt', completedAt: 'mutantCompletedAt' },
    'mutant-refactor': { startedAt: 'mutantRefactorStartedAt', completedAt: 'mutantRefactorCompletedAt' },
};
/**
 * Returns the duration of a phase in milliseconds, or undefined if timestamps are missing.
 */
export function getPhaseDuration(task, phase) {
    const timestamps = PHASE_TIMESTAMPS[phase];
    if (!timestamps)
        return undefined;
    const startedAt = task[timestamps.startedAt];
    const completedAt = task[timestamps.completedAt];
    if (!startedAt || !completedAt)
        return undefined;
    const duration = new Date(completedAt).getTime() - new Date(startedAt).getTime();
    return Number.isNaN(duration) ? undefined : duration;
}
/** Helper: is adversarial review phase fully done (clean or refactored) */
function isAdversarialDone(task) {
    if (!task.adversarialReviewSha)
        return false;
    if (task.adversarialVerdict === 'clean')
        return true;
    if (task.adversarialVerdict === 'needs-refactoring' && task.adversarialRefactorCommitSha)
        return true;
    return false;
}
