import React from 'react';
import { cn } from '@/lib/utils';
import { Bot } from 'lucide-react';
import { SelectableCard } from './ui/selectable-card';
import type { Agent } from '../types';

interface AgentListProps {
  agents: Agent[];
  selectedAgentId: string | null;
  onSelectAgent: (agentId: string) => void;
}

interface AgentCardProps {
  agent: Agent;
  isSelected: boolean;
  onClick: () => void;
}

const AgentCard: React.FC<AgentCardProps> = ({ agent, isSelected, onClick }) => {
  return (
    <SelectableCard isSelected={isSelected} onClick={onClick}>
      <div className="flex items-start gap-3">
        <div className={cn(
          'p-2 rounded-lg',
          isSelected ? 'bg-primary/10' : 'bg-muted'
        )}>
          <Bot className="h-4 w-4 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-medium text-sm truncate">{agent.name}</h3>
            {agent.origin && (
              <span
                className="px-1.5 py-0.5 text-xs rounded-full bg-green-500/10 text-green-600 whitespace-nowrap"
                title={`Recommended: ${agent.origin.recommendationName} (accepted ${new Date(agent.origin.acceptedAt).toLocaleDateString()})`}
              >
                Recommended
              </span>
            )}
          </div>
          {agent.description && (
            <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
              {agent.description}
            </p>
          )}
          {agent.tags && agent.tags.length > 0 && (
            <div className="flex flex-wrap gap-1 mt-2">
              {agent.tags.slice(0, 3).map((tag) => (
                <span
                  key={tag}
                  className="px-1.5 py-0.5 text-xs rounded bg-muted text-muted-foreground"
                >
                  {tag}
                </span>
              ))}
              {agent.tags.length > 3 && (
                <span className="px-1.5 py-0.5 text-xs text-muted-foreground">
                  +{agent.tags.length - 3}
                </span>
              )}
            </div>
          )}
        </div>
      </div>
    </SelectableCard>
  );
};

const AgentList: React.FC<AgentListProps> = ({
  agents,
  selectedAgentId,
  onSelectAgent,
}) => {
  if (agents.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">🤖</div>
        <p className="text-muted-foreground text-center">No agents installed</p>
        <p className="text-muted-foreground/70 text-sm text-center mt-2">
          Run <code className="px-1 bg-muted rounded">npx tiny-brain analyse</code> to install agents
        </p>
      </div>
    );
  }

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Installed agents">
      {agents.map((agent) => (
        <AgentCard
          key={agent.id}
          agent={agent}
          isSelected={agent.id === selectedAgentId}
          onClick={() => onSelectAgent(agent.id)}
        />
      ))}
    </div>
  );
};

export default AgentList;
