const defaultFlags: FeatureFlags = { enableTDD: true, enableSDD: true, enableADR: true };

interface ModeCheckItem {
  label: string;
  complete: boolean;
}

const ModeSection: React.FC<{ label: string; enabled: boolean; items: ModeCheckItem[] }> = ({ label, enabled, items }) => {
  const allConfigured = items.every(item => item.complete);

  let badgeLabel: string;
  let badgeVariant: 'enabled' | 'misconfigured' | 'disabled';

  if (!enabled) {
    badgeLabel = 'Disabled';
    badgeVariant = 'disabled';
  } else if (allConfigured) {
    badgeLabel = 'Enabled';
    badgeVariant = 'enabled';
  } else {
    badgeLabel = 'Mis-configured';
    badgeVariant = 'misconfigured';
  }

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
      <div className="flex items-center justify-between px-3 py-2 bg-gray-50 dark:bg-gray-800/50">
        <span className="text-sm font-semibold">{label}</span>
        <FlagBadge label={badgeLabel} variant={badgeVariant} />
      </div>
      <div className="px-3 py-2 space-y-1.5">
        {items.map(item => (
          <div key={item.label} className="flex items-center gap-2 text-sm">
            {item.complete ? (
              <CheckCircle2 className="h-4 w-4 text-green-500 flex-shrink-0" />
            ) : (
              <div className="h-4 w-4 rounded-full border-2 border-gray-300 dark:border-gray-600 flex-shrink-0" />
            )}
            <span className={item.complete ? 'text-foreground' : 'text-muted-foreground'}>{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const GuardrailOverviewContent: React.FC<{ health: ConfigHealth; flags: FeatureFlags | null; onRunAnalysis: () => void; analyzing: boolean; hasClaudeCli: boolean }> = ({ health, flags, onRunAnalysis, analyzing, hasClaudeCli }) => {
  const resolvedFlags = flags ?? defaultFlags;
  const allHooksInstalled = [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit].every(h => h.installed && h.signed);
  const claudeMdPresent = health.contextBlock.present;
  const permissionsPresent = health.permissions.present && health.permissions.missing.length === 0;
  const directoriesComplete = health.directories.missing.length === 0;

  const tddItems: ModeCheckItem[] = [
    { label: 'Git hooks', complete: allHooksInstalled },
    { label: 'TDD workflow', complete: claudeMdPresent },
    { label: 'sync-progress CLI', complete: true },
  ];

  const sddItems: ModeCheckItem[] = [
    { label: 'SDD workflow', complete: claudeMdPresent },
    { label: 'Permissions', complete: permissionsPresent },
  ];

  const adrItems: ModeCheckItem[] = [
    { label: 'ADR directory', complete: directoriesComplete },
    { label: 'ADR workflow', complete: claudeMdPresent },
  ];

  return (
    <div className="space-y-4">
      <div className={`p-4 rounded-lg bg-gradient-to-r border ${getStatusBg(health.status)}`}>
        <div className="flex items-center gap-3">
          {getStatusIcon(health.status)}
          <div className="flex-1">
            <p className="font-semibold">{getStatusLabel(health.status)}</p>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {health.status === 'healthy'
                ? 'Repository configuration is complete'
                : 'Re-run analysis to fix configuration issues'}
            </p>
          </div>
          {health.status !== 'healthy' && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span>
                  <Button
                    onClick={onRunAnalysis}
                    disabled={!hasClaudeCli || analyzing}
                    size="sm"
                    variant="outline"
                  >
                    {analyzing ? (
                      <>
                        <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                        Fixing...
                      </>
                    ) : (
                      <>
                        <Play className="h-3.5 w-3.5 mr-1.5" />
                        Re-run Analysis
                      </>
                    )}
                  </Button>
                </span>
              </TooltipTrigger>
              {!hasClaudeCli && (
                <TooltipContent>
                  Claude CLI required - use the /analyse command in Claude Code instead
                </TooltipContent>
              )}
            </Tooltip>
          )}
        </div>
        {health.status !== 'healthy' && (() => {
          const issues = getConfigIssues(health);
          return issues.length > 0 ? (
            <ul data-testid="config-issues" className="mt-2 space-y-1">
              {issues.map((issue) => (
                <li key={issue} className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                  <AlertCircle className="h-3.5 w-3.5 flex-shrink-0" />
                  {issue}
                </li>
              ))}
            </ul>
          ) : null;
        })()}
      </div>

      <ModeSection label="TDD" enabled={resolvedFlags.enableTDD} items={tddItems} />
      <ModeSection label="SDD" enabled={resolvedFlags.enableSDD} items={sddItems} />
      <ModeSection label="ADR" enabled={resolvedFlags.enableADR} items={adrItems} />
    </div>
  );
};


