// --- Step 3: Recommendations ---

const RecommendationsStep: React.FC<{
  recommendations: DashboardRecommendation[];
  dismissed: DismissedRecommendation[];
  dismissedExpanded: boolean;
  setDismissedExpanded: (expanded: boolean) => void;
  onAccept: (rec: DashboardRecommendation) => void;
  onDismiss: (rec: DashboardRecommendation) => void;
  onRestore: (item: DismissedRecommendation) => void;
  acceptingIds: Set<string>;
  acceptResults: Map<string, AcceptResult>;
}> = ({ recommendations, dismissed, dismissedExpanded, setDismissedExpanded, onAccept, onDismiss, onRestore, acceptingIds, acceptResults }) => {
  const [validationStates, setValidationStates] = useState<Record<string, RecommendationValidationState>>({});

  const handleAnalyse = async (rec: DashboardRecommendation) => {
    // Use cached validation from recommendation data if available
    if (rec.validation) {
      setValidationStates((prev) => ({
        ...prev,
        [rec.id]: { status: 'success', result: rec.validation as SkillValidationResult },
      }));
      return;
    }

    // No cached validation available - show fallback message
    setValidationStates((prev) => ({
      ...prev,
      [rec.id]: { status: 'error', message: 'Validation not available - accept to validate locally' },
    }));
  };
  const groupedRecs = recommendations.reduce<Record<string, DashboardRecommendation[]>>((acc, rec) => {
    const group = acc[rec.type] ?? [];
    group.push(rec);
    acc[rec.type] = group;
    return acc;
  }, {});

  const typeOrder = ['skill', 'agent', 'hook'] as const;

  return (
    <section>
      <div className="mb-4">
        <p className="text-sm text-muted-foreground">
          Here are recommendations to help agentic work well
        </p>
      </div>

      {recommendations.length === 0 ? (
        <div className="text-center py-8 text-muted-foreground">
          <div className="text-4xl mb-2">&#10024;</div>
          <p className="font-medium">All caught up</p>
          <p className="text-sm mt-1">No pending recommendations</p>
        </div>
      ) : (
        <div className="space-y-6">
          {typeOrder.map(type => {
            const recs = groupedRecs[type];
            if (!recs || recs.length === 0) return null;

            return (
              <div key={type}>
                <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3 flex items-center gap-2">
                  {typeIcons[type]}
                  {type === 'skill' ? 'Skills' : type === 'agent' ? 'Agents' : 'Hooks'}
                  <Badge variant="secondary" className="ml-1">{recs.length}</Badge>
                </h3>
                <div className="space-y-3">
                  {recs.map(rec => (
                    <RecommendationCard
                      key={rec.id}
                      recommendation={rec}
                      onAccept={() => onAccept(rec)}
                      onDismiss={() => onDismiss(rec)}
                      isAccepting={acceptingIds.has(rec.id)}
                      acceptResult={acceptResults.get(rec.id)}
                      validationState={validationStates[rec.id]}
                      onAnalyse={() => handleAnalyse(rec)}
                    />
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Dismissed Section */}
      {dismissed.length > 0 && (
        <div className="mt-6">
          <button
            onClick={() => setDismissedExpanded(!dismissedExpanded)}
            className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
          >
            {dismissedExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
            <span>Dismissed</span>
            <Badge variant="secondary">{dismissed.length}</Badge>
          </button>

          {dismissedExpanded && (
            <div className="mt-3 space-y-2">
              {dismissed.map(item => (
                <div
                  key={item.recommendation.id}
                  className="flex items-center justify-between p-3 border border-border rounded-lg bg-muted/30"
                >
                  <div className="flex items-center gap-3">
                    <span className={`text-xs px-2 py-0.5 rounded ${typeBadgeColors[item.recommendation.type]?.bg ?? ''} ${typeBadgeColors[item.recommendation.type]?.text ?? ''}`}>
                      {item.recommendation.type}
                    </span>
                    <span className="text-sm">{item.recommendation.name}</span>
                  </div>
                  <button
                    onClick={() => onRestore(item)}
                    className="text-xs px-2 py-1 rounded border border-border hover:bg-accent transition-colors"
                    aria-label={`Restore ${item.recommendation.name}`}
                  >
                    Restore
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </section>
  );
};

