import React, { useState } from 'react';
import { Loader2, Play } from 'lucide-react';
import GradePill from './GradePill';
import { SkillInvocationPanel } from './SkillInvocationPanel';
import { useSkillInvocation } from '../hooks/useSkillInvocation';
import { useApiKeyStatus } from '../hooks/useApiKeyStatus';
import type { ParsedPlanData, ImprovementPhase } from '../types';

interface QualityImprovementPlanProps {
  plan: ParsedPlanData | null;
}

function PhaseSection({ phase }: { phase: ImprovementPhase }) {
  const [expanded, setExpanded] = useState(true);

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800 text-left"
      >
        <span className="font-medium text-gray-900 dark:text-gray-100">
          Phase {phase.phase}: {phase.name}
        </span>
        <div className="flex items-center gap-2">
          <span className="text-xs text-gray-500 dark:text-gray-400">
            {phase.totalEffortHours}h
          </span>
          <GradePill grade={phase.projectedGrade} />
          <span className="text-gray-400">{expanded ? '▾' : '▸'}</span>
        </div>
      </button>

      {expanded && (
        <div className="p-3">
          <p className="text-sm text-gray-600 dark:text-gray-400 mb-3">
            {phase.description}
          </p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mb-2">
            Projected: {phase.projectedScore}/100
          </p>

          {phase.initiatives.length > 0 && (
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                  <th className="pb-1 font-medium">Initiative</th>
                  <th className="pb-1 font-medium">Category</th>
                  <th className="pb-1 font-medium text-right">Effort (hrs)</th>
                  <th className="pb-1 font-medium text-right">Score Gain</th>
                </tr>
              </thead>
              <tbody>
                {phase.initiatives.map((init) => (
                  <tr key={init.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0">
                    <td className="py-1.5 text-gray-900 dark:text-gray-100">{init.title}</td>
                    <td className="py-1.5 text-gray-600 dark:text-gray-400">{init.primaryCategory}</td>
                    <td className="py-1.5 text-right text-gray-600 dark:text-gray-400">{init.effortHours}</td>
                    <td className="py-1.5 text-right text-green-600 dark:text-green-400">+{init.expectedScoreGain.toFixed(1)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}

export const QualityImprovementPlan: React.FC<QualityImprovementPlanProps> = ({ plan }) => {
  const [showPanel, setShowPanel] = useState(false);
  const { invoke, cancel, isRunning, output, toolCalls, error } = useSkillInvocation();
  const { hasClaudeCli, isLoading: isApiKeyLoading } = useApiKeyStatus();

  if (!plan) return null;

  const handleImplementPlan = () => {
    setShowPanel(true);
    invoke(
      'quality',
      `Implement the quality improvement plan. Run the implement-plan operation with planId="${plan.planId}". After creating fixes, sync each fix file.`,
      { planId: plan.planId },
    );
  };

  const handleClosePanel = () => {
    if (!isRunning) {
      setShowPanel(false);
    }
  };

  return (
    <div className="space-y-4">
      {!isApiKeyLoading && (
        <div>
          <button
            type="button"
            onClick={handleImplementPlan}
            disabled={!hasClaudeCli || isRunning}
            className="inline-flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isRunning ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Implementing...
              </>
            ) : (
              <>
                <Play className="h-4 w-4" />
                Implement Plan
              </>
            )}
          </button>
          {!hasClaudeCli && (
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              Claude CLI required - use /quality implement in Claude Code instead
            </p>
          )}
        </div>
      )}

      <p className="text-sm text-gray-600 dark:text-gray-400">
        {plan.executiveSummary}
      </p>

      <div className="space-y-3">
        {plan.phases.map((phase) => (
          <PhaseSection key={phase.phase} phase={phase} />
        ))}
      </div>

      <SkillInvocationPanel
        isOpen={showPanel}
        onClose={handleClosePanel}
        skillName="quality"
        output={output}
        toolCalls={toolCalls}
        isRunning={isRunning}
        error={error}
        onCancel={cancel}
      />
    </div>
  );
};
