import React, { useState, useCallback } from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, GitCommit, FileCode, Wrench, AlertCircle, Archive, Copy, Check } from 'lucide-react';
import { formatDistanceToNow, format } from 'date-fns';
import type { Fix, Task } from '../types';
import TestPlanBadge from './TestPlanBadge';
import TestPlanDetail from './TestPlanDetail';
import TaskRow from './TaskRow';
import TaskDetailPanel from './TaskDetailPanel';

interface FixDetailProps {
  fix: Fix;
  repoId: string;
  onArchive?: () => void;
  onUnarchive?: () => void;
}

const severityColors = {
  low: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300',
  medium: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
  high: 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300',
  critical: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300',
};

const statusLabels = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
  superseded: 'Superseded',
};

const statusColors = {
  not_started: 'bg-gray-500',
  in_progress: 'bg-blue-500',
  completed: 'bg-green-500',
  superseded: 'bg-orange-500',
};

// Format date for display (e.g., "7th Jan 2026 15:17")
// Handles both date-only (2026-01-07) and full ISO timestamps
function formatDateTime(dateStr: string): string {
  const date = new Date(dateStr);
  // If it's a date-only string, don't show time
  if (dateStr.length === 10 && !dateStr.includes('T')) {
    return format(date, "do MMM yyyy");
  }
  return format(date, "do MMM yyyy HH:mm");
}


const FixDetail: React.FC<FixDetailProps> = ({ fix, repoId, onArchive, onUnarchive }) => {
  const [copiedId, setCopiedId] = useState(false);
  const [selectedTask, setSelectedTask] = useState<{ taskNumber: number; task: Task } | null>(null);
  const completedCount = fix.tasks.filter(t => t.status === 'completed').length;
  const supersededCount = fix.tasks.filter(t => t.status === 'superseded').length;
  const doneTasks = completedCount + supersededCount;
  const totalTasks = fix.tasks.length;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;

  const handleCopyId = useCallback(async () => {
    await navigator.clipboard.writeText(fix.id);
    setCopiedId(true);
    setTimeout(() => setCopiedId(false), 2000);
  }, [fix.id]);

  return (
    <div className="p-6 space-y-6 overflow-auto h-full">
      {/* Header */}
      <div className="space-y-3">
        <div className="flex items-start justify-between gap-4">
          <h2 className="text-xl font-bold">{fix.title}</h2>
          <div className="flex items-center gap-2">
            <Badge className={cn(severityColors[fix.severity])}>
              {fix.severity}
            </Badge>
            <Badge variant="outline" className="flex items-center gap-1.5 whitespace-nowrap">
              <span className={cn('w-2 h-2 rounded-full', statusColors[fix.status])} />
              {statusLabels[fix.status]}
            </Badge>
            {fix.archived === true && (
              <Badge variant="outline" className="text-muted-foreground">
                Archived
              </Badge>
            )}
            {fix.archived === true ? (
              <button
                role="button"
                onClick={onUnarchive}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                aria-label="Unarchive"
              >
                <Archive className="h-4 w-4" />
                Unarchive
              </button>
            ) : (
              <button
                role="button"
                onClick={onArchive}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                aria-label="Archive"
              >
                <Archive className="h-4 w-4" />
                Archive
              </button>
            )}
          </div>
        </div>
        <div className="flex items-center justify-between">
          <button
            onClick={handleCopyId}
            className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground transition-colors"
            title="Copy Fix ID"
          >
            {fix.id}
            {copiedId ? (
              <Check className="h-3 w-3 text-green-500" />
            ) : (
              <Copy className="h-3 w-3 opacity-50 hover:opacity-100" />
            )}
          </button>
          <span className="text-xs text-muted-foreground font-mono">{fix.filePath}</span>
        </div>

        {/* Dates - inline */}
        <div className="flex items-center gap-4 text-sm text-muted-foreground">
          {fix.reported && (
            <span>Reported: {formatDateTime(fix.reported)}</span>
          )}
          {fix.resolved && (
            <span className="flex items-center gap-1">
              <span>Resolved:</span>
              <span className="font-semibold text-green-600 dark:text-green-400">
                {formatDistanceToNow(new Date(fix.resolved), { addSuffix: true })}
              </span>
            </span>
          )}
        </div>

        {/* Progress */}
        <div>
          <div className="flex items-center justify-between text-sm mb-2">
            <span className="text-muted-foreground">Progress</span>
            <span className="font-medium">
              {totalTasks === 0
                ? '0 tasks'
                : supersededCount > 0
                  ? `${completedCount} completed, ${supersededCount} superseded / ${totalTasks} tasks (${progress}%)`
                  : `${doneTasks}/${totalTasks} tasks (${progress}%)`}
            </span>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden flex" data-testid="progress-bar">
            {completedCount > 0 && (
              <div
                data-testid="progress-completed"
                className="h-full bg-green-500 transition-all"
                style={{ width: `${Math.round((completedCount / totalTasks) * 100)}%` }}
              />
            )}
            {supersededCount > 0 && (
              <div
                data-testid="progress-superseded"
                className="h-full bg-orange-400 transition-all"
                style={{ width: `${Math.round((supersededCount / totalTasks) * 100)}%` }}
              />
            )}
          </div>
        </div>

        {/* Test Plan Summary */}
        {fix.testPlan && (
          <div className="flex items-center gap-2">
            <span className="text-sm text-muted-foreground">Tests:</span>
            <TestPlanBadge testPlan={fix.testPlan} />
          </div>
        )}
      </div>

      {/* Resolution Details - shown above tasks for resolved fixes */}
      {fix.resolution && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <CheckCircle2 className="h-5 w-5 text-green-500" />
              Resolution
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Root Cause */}
            {fix.resolution.rootCause && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <AlertCircle className="h-4 w-4" />
                  Root Cause
                </h4>
                <p className="text-sm pl-6">{fix.resolution.rootCause}</p>
              </div>
            )}

            {/* Fix Steps */}
            {fix.resolution.fix && fix.resolution.fix.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <Wrench className="h-4 w-4" />
                  Fix Applied
                </h4>
                <ol className="text-sm pl-6 space-y-1 list-decimal list-inside">
                  {fix.resolution.fix.map((step, i) => (
                    <li key={i} className="text-sm">{step}</li>
                  ))}
                </ol>
              </div>
            )}

            {/* Files Modified */}
            {fix.resolution.filesModified && fix.resolution.filesModified.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <FileCode className="h-4 w-4" />
                  Files Modified ({fix.resolution.filesModified.length})
                </h4>
                <ul className="text-xs pl-6 space-y-0.5 font-mono">
                  {fix.resolution.filesModified.map((file, i) => (
                    <li key={i} className="text-muted-foreground">{file}</li>
                  ))}
                </ul>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Test Plan Detail */}
      <TestPlanDetail testPlan={fix.testPlan} />

      {/* Tasks */}
      <div>
        <div className="flex items-center gap-2 mb-2">
          <GitCommit className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium">Tasks</span>
        </div>
        {fix.tasks.length === 0 ? (
          <p className="text-muted-foreground text-sm text-center py-4">No tasks defined</p>
        ) : (
          <div className="space-y-1">
            {fix.tasks.map((task, index) => (
              <TaskRow
                key={task.id}
                task={task}
                repoId={repoId}
                onClick={() => setSelectedTask({ taskNumber: index + 1, task })}
              />
            ))}
          </div>
        )}
      </div>

      {selectedTask && (
        <TaskDetailPanel
          isOpen={true}
          onClose={() => setSelectedTask(null)}
          repoId={repoId}
          fixId={fix.id}
          taskNumber={selectedTask.taskNumber}
          progressTask={selectedTask.task}
        />
      )}
    </div>
  );
};

export default FixDetail;
