import React, { useState } from 'react';
import { Clock, DollarSign, Tag } from 'lucide-react';
import type { TechnicalDebtSummary, QualityIssue } from '../types';

interface QualityTechnicalDebtProps {
  technicalDebt?: TechnicalDebtSummary;
  issues?: QualityIssue[];
}

const categoryColors: Record<string, string> = {
  Security: 'bg-red-500',
  Reliability: 'bg-blue-500',
  Performance: 'bg-yellow-500',
  Maintainability: 'bg-cyan-500',
  Testing: 'bg-purple-500',
  Architecture: 'bg-orange-500',
  Documentation: 'bg-blue-400',
  Operations: 'bg-gray-500',
};

const severityColors: Record<string, string> = {
  critical: 'bg-red-500',
  major: 'bg-orange-500',
  minor: 'bg-yellow-500',
  info: 'bg-blue-500',
};

function CollapsibleSection({
  title,
  icon,
  children,
}: {
  title: string;
  icon?: React.ReactNode;
  children: React.ReactNode;
}) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div className="space-y-2">
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex items-center gap-2 w-full text-left hover:opacity-80"
      >
        {icon}
        <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300">
          {title}
        </h4>
        <span className="text-gray-400 text-xs">{expanded ? '▾' : '▸'}</span>
      </button>
      {expanded && children}
    </div>
  );
}

export const QualityTechnicalDebt: React.FC<QualityTechnicalDebtProps> = ({
  technicalDebt,
  issues = [],
}) => {
  if (!technicalDebt) {
    return null;
  }

  const { totalHours, hoursByCategory, hoursBySeverity, estimatedCost, currency } = technicalDebt;

  // Sort categories by hours descending
  const sortedCategories = Object.entries(hoursByCategory)
    .sort(([, a], [, b]) => b - a);
  const maxCategoryHours = sortedCategories[0]?.[1] || 1;

  // Sort severities by hours descending
  const sortedSeverities = Object.entries(hoursBySeverity)
    .sort(([, a], [, b]) => b - a);
  const maxSeverityHours = sortedSeverities[0]?.[1] || 1;

  // Compute top themes from issues
  const themeCounts = issues.reduce((acc, issue) => {
    if (issue.theme) {
      acc[issue.theme] = (acc[issue.theme] || 0) + 1;
    }
    return acc;
  }, {} as Record<string, number>);

  const topThemes = Object.entries(themeCounts)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 5);

  // Format cost
  const formattedCost = estimatedCost
    ? new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: currency || 'USD',
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(estimatedCost)
    : null;

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-4 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Clock className="h-5 w-5 text-gray-500" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
            Technical Debt
          </h3>
          <span className="text-2xl font-bold text-gray-900 dark:text-gray-100">
            {Number.isInteger(totalHours) ? totalHours : totalHours.toFixed(1)} hours
          </span>
        </div>
        {formattedCost && (
          <div className="flex items-center gap-1 text-gray-600 dark:text-gray-400">
            <DollarSign className="h-4 w-4" />
            <span className="font-medium">{formattedCost}</span>
          </div>
        )}
      </div>

      {/* Hours by Category */}
      {sortedCategories.length > 0 && (
        <CollapsibleSection title="Hours by Category">
          <div className="space-y-2">
            {sortedCategories.map(([category, hours]) => {
              const percentage = (hours / maxCategoryHours) * 100;
              const barColor = categoryColors[category] || 'bg-gray-500';

              return (
                <div key={category} className="flex items-center gap-2">
                  <span className="w-28 text-sm text-gray-600 dark:text-gray-400 truncate">
                    {category}
                  </span>
                  <div className="flex-1 h-4 bg-gray-200 dark:bg-gray-700 rounded overflow-hidden">
                    <div
                      data-testid="category-bar"
                      className={`h-full ${barColor} transition-all`}
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <span className="w-12 text-sm text-gray-600 dark:text-gray-400 text-right">
                    {Number.isInteger(hours) ? hours : hours.toFixed(1)}h
                  </span>
                </div>
              );
            })}
          </div>
        </CollapsibleSection>
      )}

      {/* Hours by Severity */}
      {sortedSeverities.length > 0 && (
        <CollapsibleSection title="Hours by Severity">
          <div className="space-y-2">
            {sortedSeverities.map(([severity, hours]) => {
              const percentage = (hours / maxSeverityHours) * 100;
              const barColor = severityColors[severity] || 'bg-gray-500';

              return (
                <div key={severity} className="flex items-center gap-2">
                  <span className="w-28 text-sm text-gray-600 dark:text-gray-400 truncate capitalize">
                    {severity}
                  </span>
                  <div className="flex-1 h-4 bg-gray-200 dark:bg-gray-700 rounded overflow-hidden">
                    <div
                      data-testid="severity-bar"
                      className={`h-full ${barColor} transition-all`}
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <span className="w-12 text-sm text-gray-600 dark:text-gray-400 text-right">
                    {Number.isInteger(hours) ? hours : hours.toFixed(1)}h
                  </span>
                </div>
              );
            })}
          </div>
        </CollapsibleSection>
      )}

      {/* Top Themes */}
      {topThemes.length > 0 && (
        <CollapsibleSection
          title="Top Themes"
          icon={<Tag className="h-4 w-4 text-gray-500" />}
        >
          <div className="flex flex-wrap gap-2">
            {topThemes.map(([theme, count]) => (
              <span
                key={theme}
                className="px-2 py-1 text-xs font-medium rounded bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300"
              >
                {theme} ({count})
              </span>
            ))}
          </div>
        </CollapsibleSection>
      )}
    </div>
  );
};

export default QualityTechnicalDebt;
