import React from 'react';
import FixCard from './FixCard';
import type { Fix } from '../types';

interface FixListProps {
  fixes: Fix[];
  selectedFixId: string | null;
  onSelectFix: (fixId: string) => void;
}

const FixList: React.FC<FixListProps> = ({ fixes, selectedFixId, onSelectFix }) => {
  if (fixes.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">🐛</div>
        <p className="text-text-secondary text-center">No fixes found</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Use /fix skill to create a fix document
        </p>
      </div>
    );
  }

  const handleFixClick = (fixId: string) => {
    console.log('[FixList] Fix clicked:', fixId);
    onSelectFix(fixId);
  };

  // Sort fixes: started first, then not started, then resolved
  // Within each category, sort by most recently updated first
  const statusOrder: Record<string, number> = {
    in_progress: 0,    // Started
    not_started: 1,    // Not started
    completed: 2,      // Complete
    superseded: 3      // Superseded
  };

  // Get the most recent update date for a fix
  const getLastUpdated = (fix: Fix): number => {
    // For resolved fixes, use resolved date
    if (fix.resolved) {
      return new Date(fix.resolved).getTime();
    }
    // Check task dates for most recent activity
    const taskDates = fix.tasks
      .flatMap(t => [t.completedAt, t.committedAt, t.testCommittedAt])
      .filter((d): d is string => !!d)
      .map(d => new Date(d).getTime());
    if (taskDates.length > 0) {
      return Math.max(...taskDates);
    }
    // Fall back to reported date
    return fix.reported ? new Date(fix.reported).getTime() : 0;
  };

  const sortedFixes = [...fixes].sort((a, b) => {
    // First sort by status category
    const statusA = statusOrder[a.status] ?? 1;
    const statusB = statusOrder[b.status] ?? 1;
    if (statusA !== statusB) return statusA - statusB;

    // Within same status, sort by most recently updated first
    return getLastUpdated(b) - getLastUpdated(a);
  });

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Fixes">
      {sortedFixes.map((fix) => (
        <FixCard
          key={fix.id}
          fix={fix}
          isSelected={fix.id === selectedFixId}
          onClick={() => handleFixClick(fix.id)}
        />
      ))}
    </div>
  );
};

export default FixList;
