import React from 'react';
import { LucideIcon, PanelLeft } from 'lucide-react';

export interface SidebarItem {
  id: string;
  title: string;
  icon: LucideIcon;
  color: string;
}

export interface SidebarSection {
  id: string;
  title?: string;
  items: SidebarItem[];
}

interface SidebarProps {
  sections: SidebarSection[];
  selectedItemId: string | null;
  onItemSelect: (itemId: string) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  sections,
  selectedItemId,
  onItemSelect,
  isCollapsed,
  onToggleCollapse
}) => {
  return (
    <aside className={`${isCollapsed ? 'w-16' : 'w-48'} transition-all duration-200 bg-gray-50 dark:bg-gray-900 border-r h-full flex flex-col`}>
      <nav className="flex-1 overflow-y-auto p-2">
        {sections.map((section, sectionIndex) => (
          <div key={section.id} className={sectionIndex > 0 ? 'mt-6' : ''}>
            {section.title && !isCollapsed && (
              <h3 className="px-3 mb-2 text-xs font-semibold text-gray-500 uppercase tracking-wider">
                {section.title}
              </h3>
            )}
            <ul className="space-y-1">
              {section.items.map((item) => {
                const isSelected = selectedItemId === item.id;
                const baseClasses = 'flex items-center gap-3 px-3 py-2 rounded-lg transition-all duration-150 cursor-pointer';
                
                // Determine background color based on item color
                const getBackgroundClasses = () => {
                  if (!isSelected) return 'hover:bg-gray-100 dark:hover:bg-gray-800';
                  
                  switch(item.color) {
                    case 'text-blue-500':
                      return 'bg-blue-100 dark:bg-blue-900/30 hover:bg-blue-200 dark:hover:bg-blue-900/40';
                    case 'text-orange-500':
                      return 'bg-orange-100 dark:bg-orange-900/30 hover:bg-orange-200 dark:hover:bg-orange-900/40';
                    case 'text-green-500':
                      return 'bg-green-100 dark:bg-green-900/30 hover:bg-green-200 dark:hover:bg-green-900/40';
                    case 'text-purple-500':
                      return 'bg-purple-100 dark:bg-purple-900/30 hover:bg-purple-200 dark:hover:bg-purple-900/40';
                    case 'text-red-500':
                      return 'bg-red-100 dark:bg-red-900/30 hover:bg-red-200 dark:hover:bg-red-900/40';
                    case 'text-yellow-500':
                      return 'bg-yellow-100 dark:bg-yellow-900/30 hover:bg-yellow-200 dark:hover:bg-yellow-900/40';
                    case 'text-indigo-500':
                      return 'bg-indigo-100 dark:bg-indigo-900/30 hover:bg-indigo-200 dark:hover:bg-indigo-900/40';
                    case 'text-pink-500':
                      return 'bg-pink-100 dark:bg-pink-900/30 hover:bg-pink-200 dark:hover:bg-pink-900/40';
                    case 'text-gray-500':
                    default:
                      return 'bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700';
                  }
                };
                
                return (
                  <li key={item.id}>
                    <button
                      onClick={() => onItemSelect(item.id)}
                      className={`${baseClasses} ${getBackgroundClasses()} w-full text-left`}
                      title={isCollapsed ? item.title : undefined}
                    >
                      <item.icon 
                        className={`h-5 w-5 flex-shrink-0 transition-colors ${item.color}`} 
                      />
                      {!isCollapsed && (
                        <span className={`font-medium ${
                          isSelected ? 'text-gray-900 dark:text-white' : 'text-gray-700 dark:text-gray-300'
                        }`}>
                          {item.title}
                        </span>
                      )}
                    </button>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </nav>

      {/* Collapse Toggle - Bottom aligned */}
      <div className="p-2">
        <button
          onClick={onToggleCollapse}
          className="w-full flex items-center gap-3 px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          aria-label="Toggle sidebar"
        >
          <PanelLeft className="h-5 w-5 flex-shrink-0 text-gray-500" />
        </button>
      </div>
    </aside>
  );
};