import React from 'react';
import {
  Shield,
  HeartPulse,
  Zap,
  Wrench,
  TestTube,
  Boxes,
  FileText,
  Settings,
  LucideIcon,
} from 'lucide-react';
import type { QualityIssue, CategoryScore } from '../types';
import GradePill from './GradePill';

interface CategoryConfig {
  name: string;
  weight: number;
  icon: LucideIcon;
  color: string;
  bgColor: string;
}

const categories: CategoryConfig[] = [
  { name: 'Security', weight: 15, icon: Shield, color: 'text-red-500', bgColor: 'bg-red-500/10' },
  { name: 'Reliability', weight: 10, icon: HeartPulse, color: 'text-blue-500', bgColor: 'bg-blue-500/10' },
  { name: 'Performance', weight: 10, icon: Zap, color: 'text-yellow-500', bgColor: 'bg-yellow-500/10' },
  { name: 'Maintainability', weight: 5, icon: Wrench, color: 'text-cyan-500', bgColor: 'bg-cyan-500/10' },
  { name: 'Testing', weight: 5, icon: TestTube, color: 'text-purple-500', bgColor: 'bg-purple-500/10' },
  { name: 'Architecture', weight: 5, icon: Boxes, color: 'text-orange-500', bgColor: 'bg-orange-500/10' },
  { name: 'Documentation', weight: 3, icon: FileText, color: 'text-blue-400', bgColor: 'bg-blue-400/10' },
  { name: 'Operations', weight: 3, icon: Settings, color: 'text-gray-500', bgColor: 'bg-gray-500/10' },
];

interface QualityCategoryGridProps {
  issues?: QualityIssue[];
  categoryScores?: CategoryScore[];
}

export const QualityCategoryGrid: React.FC<QualityCategoryGridProps> = ({ issues = [], categoryScores }) => {
  // Count issues per category
  const issueCounts = issues.reduce((acc, issue) => {
    acc[issue.category] = (acc[issue.category] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Create lookup map for category scores
  const scoresByCategory = categoryScores?.reduce((acc, score) => {
    acc[score.category] = score;
    return acc;
  }, {} as Record<string, CategoryScore>) ?? {};

  const hasScores = categoryScores && categoryScores.length > 0;

  return (
    <div className="grid grid-cols-4 gap-3">
      {categories.map((category) => {
        const Icon = category.icon;
        const issueCount = issueCounts[category.name] || 0;
        const score = scoresByCategory[category.name];

        return (
          <div
            key={category.name}
            className="relative rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 p-3 hover:border-purple-500/50 transition-colors"
          >
            {/* Top row: Icon + Category + Grade */}
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className={`flex items-center justify-center w-6 h-6 rounded ${category.bgColor}`}>
                  <Icon className={`h-3.5 w-3.5 ${category.color}`} />
                </div>
                <span className="text-xs font-medium text-gray-700 dark:text-gray-300">
                  {category.name}
                </span>
              </div>
              {hasScores && score && (
                <GradePill grade={score.grade} size="sm" />
              )}
            </div>
            {/* Bottom row: Issue count + Deduction */}
            <div className="flex items-center justify-between">
              <span className={`text-sm font-bold ${issueCount > 0 ? 'text-red-600 dark:text-red-400' : 'text-gray-400 dark:text-gray-500'}`}>
                {issueCount} {issueCount === 1 ? 'issue' : 'issues'}
              </span>
              {hasScores && score && score.deduction > 0 && (
                <span className="text-xs font-medium text-red-600 dark:text-red-400">
                  -{Number.isInteger(score.deduction) ? score.deduction : score.deduction.toFixed(1)} pts
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default QualityCategoryGrid;
