import type React from 'react';
import type { TaskRowTask, TddPhase } from '../types';
import { deriveTddPhase, isPhaseComplete, isPhaseInProgress } from '../utils/tdd-phases';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';

interface TddPhasePipelineProps {
  task: TaskRowTask;
  mutationTestingEnabled?: boolean;
  onPhaseClick?: (phase: TddPhase, commitSha: string) => void;
}

interface PhaseIcon {
  readonly emoji: string;
  readonly label: string;
  readonly phase: TddPhase;
}

const BASE_PHASES: readonly PhaseIcon[] = [
  { emoji: '\u{1F534}', label: 'Red', phase: 'red' },
  { emoji: '\u{1F7E2}', label: 'Green', phase: 'green' },
  { emoji: '\u{1F608}', label: 'Adversarial', phase: 'adversarial' },
  { emoji: '\u21A9\uFE0F', label: 'Refactor', phase: 'adversarial-refactor' },
];

const MUTATION_PHASES: readonly PhaseIcon[] = [
  { emoji: '\u{1F9DF}', label: 'Mutant', phase: 'mutant' },
  { emoji: '\u21A9\uFE0F', label: 'Refactor', phase: 'mutant-refactor' },
];

const getPhaseCommitSha = (task: TaskRowTask, phase: TddPhase): string | undefined => {
  switch (phase) {
    case 'red': return task.testCommitSha;
    case 'green': return task.commitSha;
    case 'adversarial': return task.adversarialReviewSha ?? task.commitSha;
    case 'adversarial-refactor': return task.adversarialRefactorCommitSha;
    case 'mutant': return task.mutantReviewSha ?? task.commitSha;
    case 'mutant-refactor': return task.mutantRefactorCommitSha;
    default: return undefined;
  }
};

const isPhaseEffectivelyComplete = (
  task: TaskRowTask,
  phase: TddPhase,
  phases: readonly PhaseIcon[],
  index: number,
): boolean => {
  if (isPhaseComplete(task, phase)) {
    return true;
  }

  // Skip-through: if a refactor phase is not complete but a subsequent phase IS complete,
  // treat the refactor as complete
  if (phase === 'adversarial-refactor') {
    const subsequentPhases = phases.slice(index + 1);
    return subsequentPhases.some((p) => isPhaseComplete(task, p.phase));
  }

  return false;
};

const isRefactorNotNeeded = (task: TaskRowTask, phase: TddPhase, mutationTestingEnabled: boolean): boolean => {
  const derived = deriveTddPhase(task, mutationTestingEnabled);
  if (phase === 'adversarial-refactor') {
    return !!task.adversarialReviewSha && !task.adversarialRefactorCommitSha
      && derived === 'complete';
  }
  if (phase === 'mutant-refactor') {
    return !!task.mutantReviewSha && !task.mutantRefactorCommitSha
      && derived === 'complete';
  }
  return false;
};

const getPhaseTitle = (label: string, complete: boolean, inProgress: boolean, notNeeded: boolean, commitSha: string | undefined): string => {
  if (complete && commitSha) {
    return `${label}: ${commitSha.substring(0, 7)}`;
  }
  if (complete) {
    return `${label}: complete`;
  }
  if (notNeeded) {
    return `${label}: not needed`;
  }
  if (inProgress) {
    return `${label}: in progress`;
  }
  return `${label}: not yet started`;
};

const TddPhasePipeline: React.FC<TddPhasePipelineProps> = ({
  task,
  mutationTestingEnabled = false,
  onPhaseClick,
}) => {
  const phases: readonly PhaseIcon[] = mutationTestingEnabled
    ? [...BASE_PHASES, ...MUTATION_PHASES]
    : BASE_PHASES;

  return (
    <span className="inline-flex items-center gap-3 mr-1">
      {phases.map((phaseIcon, index) => {
        const complete = isPhaseEffectivelyComplete(task, phaseIcon.phase, phases, index);
        const commitSha = getPhaseCommitSha(task, phaseIcon.phase);
        const isCurrent = isPhaseInProgress(task, phaseIcon.phase);
        const isClickable = complete && commitSha !== undefined && onPhaseClick !== undefined;
        const notNeeded = isRefactorNotNeeded(task, phaseIcon.phase, mutationTestingEnabled);
        const title = getPhaseTitle(phaseIcon.label, complete, isCurrent, notNeeded, commitSha);

        const baseClass = `text-base w-8 h-8 flex items-center justify-center rounded-full${isCurrent ? ' animate-ring-pulse bg-gradient-to-br from-blue-300/70 to-pink-300/70 dark:from-blue-800/40 dark:to-pink-800/40' : ''}`;
        const emojiContent = (
          <span style={{ opacity: complete ? 1 : 0.25 }}>
            {phaseIcon.emoji}
          </span>
        );

        const trigger = isClickable ? (
          <TooltipTrigger asChild>
            <button
              type="button"
              aria-label={title}
              className={`${baseClass} cursor-pointer border-0 bg-transparent p-0`}
              onClick={(e) => { e.stopPropagation(); onPhaseClick(phaseIcon.phase, commitSha); }}
            >
              {emojiContent}
            </button>
          </TooltipTrigger>
        ) : (
          <TooltipTrigger asChild>
            <span aria-label={title} role="img" className={baseClass}>
              {emojiContent}
            </span>
          </TooltipTrigger>
        );

        return (
          <Tooltip key={phaseIcon.phase}>
            {trigger}
            <TooltipContent side="bottom">{title}</TooltipContent>
          </Tooltip>
        );
      })}
    </span>
  );
};

export default TddPhasePipeline;
