import type { TaskRowTask, TddPhase } from '../types';
import {
  derivePhase as coreDerivePhase,
  isPhaseComplete as coreIsPhaseComplete,
  isPhaseInProgress as coreIsPhaseInProgress,
} from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { PhaseDeriveInput, DerivedTddPhase } from '@magic-ingredients/tiny-brain-core/phase-derivation';

export const TDD_PHASES: readonly TddPhase[] = Object.freeze([
  'red',
  'green',
  'adversarial',
  'adversarial-refactor',
  'mutant',
  'mutant-refactor',
  'complete',
] as const);

export const deriveTddPhase = (task: TaskRowTask, mutationTestingEnabled = false): TddPhase => {
  const derived = coreDerivePhase(task as PhaseDeriveInput, {
    combineRedGreenCommits: false,
    enableAdversarial: true,
    hasMutantCapability: mutationTestingEnabled,
  });
  // Map 'idle' to 'red' for dashboard display (pipeline won't show anyway if idle)
  if (derived === 'idle') return 'red';
  return derived as TddPhase;
};

// Phase complete: completion SHA for that phase is set
export const isPhaseComplete = (task: TaskRowTask, phase: TddPhase): boolean => {
  return coreIsPhaseComplete(task as PhaseDeriveInput, phase as DerivedTddPhase);
};

// Phase in progress: previous phase done but this one not yet
export const isPhaseInProgress = (task: TaskRowTask, phase: TddPhase): boolean => {
  return coreIsPhaseInProgress(task as PhaseDeriveInput, phase as DerivedTddPhase);
};
